package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import java.io.File;import java.time.*;import java.util.*;import java.util.function.Supplier;import org.junit.Test;import static org.junit.Assert.*;
/** Private saved-record journey only. No tracking, alarm, permission or output activities. */
public final class RecordAchievementsFlowTest {
 final SunriseTimeFlowTest ui=new SunriseTimeFlowTest();
 void launch(Class<? extends Activity> type,long id)throws Exception{Activity a=ui.i.startActivitySync(new Intent(ui.c,type).putExtra("record",id).putExtra("visualReview",true).putExtra("verificationLabel","Private recorded-evidence fixture").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));ui.current=a;ui.await("focused recorded fixture",a::hasWindowFocus);}
 void capture(String name)throws Exception{ui.frame();assertTrue(ui.d.takeScreenshot(new File(ui.folder(),"record-achievements-"+name+".png")));}
 void recreate(String label)throws Exception{Activity old=ui.current;ui.i.runOnMainSync(old::recreate);ui.await("new focused achievements owner",()->ui.current!=old&&ui.current.hasWindowFocus());ui.shown(label);}
 @Test public void reportActionPrivateSavedEvidenceEditSearchRecreationAndReopenRecalculate()throws Exception{
  assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",ui.d.executeShellCommand("getprop ro.kernel.qemu").trim());String name="achievement-flow-"+UUID.randomUUID();Records.Factory oldFactory=Records.factory;Supplier<Instant> oldClock=RecordAchievementsActivity.clock;Map<String,?> original=new HashMap<>(Prefs.of(ui.c).getAll());Application app=(Application)ui.c.getApplicationContext();Application.ActivityLifecycleCallbacks observer=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue("Only private record screens",a instanceof RecordAchievementsActivity||a instanceof RecordReportActivity||a instanceof HistoryActivity||a instanceof RecordEditorActivity);ui.owned.add(a);}public void onActivityResumed(Activity a){ui.current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(observer);
  try{Records.factory=c->new Store(c,name);RecordAchievementsActivity.clock=()->Instant.ofEpochMilli(RecordAchievementsStorageTest.NOW);launch(RecordAchievementsActivity.class,0);ui.shown("No qualifying nights yet");capture("empty");long id;try(Store s=new Store(ui.c,name)){id=RecordAchievementsStorageTest.motion(s,"2026-10-20T00:00:00Z",240);s.getWritableDatabase().execSQL("UPDATE sessions SET note=? WHERE id=?",new Object[]{"Milestone searchable fixture",id});}launch(RecordReportActivity.class,id);ui.shown("Report options");ui.click("Report options");ui.shown("Recorded signals & notes");ui.click("Achievements");ui.shown("Qualifying recorded nights 1");capture("first");recreate("Qualifying recorded nights 1");ui.shown("First recorded night: 1 of 1");capture("recreated");
   ui.click("Review saved records");ui.shown("Sleep history");ui.click("Search records");ui.input("Search notes and tags","Milestone searchable fixture");String row;try(Store s=new Store(ui.c,name)){RecordEntry r=Records.get(s,id);row="Open record "+id+", "+r.day(Math.max(0,Math.min(1439,Prefs.number(ui.c,"statsCutoff",0))))+", "+RecordUi.duration(r.duration())+", "+r.provenance();}ui.shown(row);capture("search");ui.click(row);ui.shown("Edit sleep");ui.i.runOnMainSync(()->{View note=ui.find(ui.root(),"Notes or dream");assertNotNull(note);note.requestRectangleOnScreen(new android.graphics.Rect(0,0,note.getWidth(),note.getHeight()),false);});ui.input("Notes or dream","Milestone saved-note fixture");ui.click("Save changes");ui.await("actual note save",()->{try(Store s=new Store(ui.c,name)){return Records.get(s,id).edit.note.equals("Milestone saved-note fixture");}});launch(RecordAchievementsActivity.class,0);ui.shown("Qualifying recorded nights 1");
   try(Store s=new Store(ui.c,name)){RecordEntry r=Records.get(s,id);RecordDraft trimmed=r.edit.copy();trimmed.start+=2*RecordAchievementsStorageTest.HOUR;Records.save(s,id,trimmed,r.updated,RecordAchievementsStorageTest.NOW+1);}ui.click("Refresh achievements");ui.shown("Qualifying recorded nights 0");ui.shown("No qualifying nights yet");capture("edited");launch(RecordAchievementsActivity.class,0);ui.shown("Qualifying recorded nights 0");try(Store s=new Store(ui.c,name)){assertEquals(240,s.rows("SELECT id FROM epochs WHERE session=?",""+id).size());assertEquals("Milestone saved-note fixture",Records.get(s,id).edit.note);assertEquals(2*RecordAchievementsStorageTest.HOUR,Records.get(s,id).duration());}Records.factory=context->{throw new IllegalStateException("Private fixture read failure; no records changed.");};launch(RecordAchievementsActivity.class,0);ui.shown("Achievements read error");capture("error");Records.factory=c->new Store(c,name);ui.click("Retry achievements");ui.shown("Qualifying recorded nights 0");assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertEquals(original,Prefs.of(ui.c).getAll());
  }catch(Exception|AssertionError failure){try{ui.d.takeScreenshot(new File(ui.folder(),"record-achievements-failure.png"));ui.d.dumpWindowHierarchy(new File(ui.folder(),"record-achievements-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;
  }finally{ui.i.runOnMainSync(()->{for(Activity a:ui.owned)if(!a.isDestroyed())a.finish();});ui.await("record fixtures destroyed",()->ui.owned.stream().allMatch(Activity::isDestroyed));for(Activity a:ui.owned)if(a instanceof RecordAchievementsActivity x)x.awaitReaders(12000);else if(a instanceof RecordReportActivity x)x.awaitReaders(12000);else if(a instanceof HistoryActivity x)x.awaitReaders(12000);else if(a instanceof RecordEditorActivity x)x.awaitReaders(12000);app.unregisterActivityLifecycleCallbacks(observer);Records.factory=oldFactory;RecordAchievementsActivity.clock=oldClock;ui.c.deleteDatabase(name);}
 }
}
